using System;
using System.Buffers.Binary;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

static byte[] EncodeRequest(string requestId)
{
    byte[] body = Encoding.ASCII.GetBytes($"REQ {requestId} GET");
    if (body.Length > ushort.MaxValue)
        throw new ArgumentOutOfRangeException(nameof(requestId));

    byte[] wire = new byte[2 + body.Length];
    BinaryPrimitives.WriteUInt16BigEndian(wire.AsSpan(0, 2), (ushort)body.Length);
    body.CopyTo(wire, 2);
    return wire;
}

static async Task SendRequestAsync(
    NetworkStream stream, string requestId, CancellationToken cancellationToken)
{
    byte[] wire = EncodeRequest(requestId);
    Console.WriteLine($"serialized id={requestId} length={wire.Length} hex={Convert.ToHexString(wire)}");

    await stream.WriteAsync(wire.AsMemory(), cancellationToken);
    Console.WriteLine($"stage=SEND request={requestId} bytes={wire.Length}");
}
